+++ b/rar2fs.c
@@ -836,10 +836,14 @@ static int __check_rar_header(const char *arch)
         if (d.OpenResult) {
                 if (h)
                         RARCloseArchive(h);
+                free(last_arch);
+                last_arch = NULL;
                 return -1;
         }
         if (RARReadHeaderEx(h, &header))  {
                 RARCloseArchive(h);
+                free(last_arch);
